{"argv":["python3","-c","open('model_lib.py','w').write(r'''
import numpy as np
def design(Xlist, zkeys, horizon=15):
    rows=[]
    for x in Xlist:
        u=x['elapsed']+horizon
        z=[x[k] for k in zkeys]
        basis=[1.0, u/60.0, (u/60.0)**2, np.exp(-u/12.0), np.exp(-u/30.0)]
        row=basis+z+[b*zz for zz in z for b in basis[1:]]
        rows.append(row)
    return np.array(rows,float)
def fit_ridge(Xtr,ytr,alpha,w=None):
    mu=Xtr.mean(0); sd=Xtr.std(0); sd[sd==0]=1.0
    Xs=(Xtr-mu)/sd
    if w is None: w=np.ones(len(ytr),float)
    else:
        w=np.array(w,float); w=w*(len(w)/w.sum())
    W=np.sqrt(w); Xw=Xs*W[:,None]
    ymu=float(np.average(ytr,weights=w))
    A=Xw.T@Xw + alpha*np.eye(Xtr.shape[1])
    b=Xw.T@((ytr-ymu)*W)
    beta=np.linalg.solve(A,b)
    return (mu,sd,ymu,beta)
def pred_ridge(model,Xte):
    mu,sd,ymu,beta=model; return ymu+((Xte-mu)/sd)@beta
def evaluate(X,y,persons,is_post,zkeys,alpha,horizon=15,train_mode='all',shrinks=(0.4,0.5,0.6,0.75,0.9,1.0),verbose=False):
    uniq=sorted(set(persons)); test_mask=is_post==1
    Xm=design(X,zkeys,horizon)
    oof=np.full(len(y),np.nan); const=np.full(len(y),np.nan)
    for p in uniq:
        te=np.where((persons==p)&test_mask)[0]
        if len(te)==0: continue
        if train_mode=='all': tr=np.where(persons!=p)[0]
        else: tr=np.where((persons!=p)&test_mask)[0]
        model=fit_ridge(Xm[tr],y[tr],alpha)
        oof[te]=pred_ridge(model,Xm[te]); const[te]=y[tr].mean()
    results={}
    for a in shrinks:
        pred=a*oof+(1-a)*const; per=[]; errs=[]
        for p in uniq:
            te=np.where((persons==p)&test_mask)[0]
            if len(te): e=np.abs(pred[te]-y[te]); per.append(e.mean()); errs.extend(e.tolist())
        results[a]=(float(np.mean(per)),float(np.mean(errs)))
    return results,oof,const
''')
print('ok')
"]}

